use super::ascii;

pub struct Inflector;

impl Inflector {
    pub fn initialize() {}

    pub fn pluralize<T: AsRef<str>>(input: T) -> String {
        let mut output = String::from(input.as_ref());
        output.push('s');
        output
    }

    pub fn singularize<T: AsRef<str>>(input: T) -> String {
        input
            .as_ref()
            .strip_suffix('s')
            .unwrap_or(input.as_ref())
            .to_string()
    }

    pub fn camelize<T: AsRef<str>>(input: T) -> String {
        Self::camelize_with_initial(input.as_ref(), false)
    }

    pub fn underscore<T: AsRef<str>>(input: T) -> String {
        let mut output = String::with_capacity(input.as_ref().len());
        let mut first = true;

        for ch in input.as_ref().chars() {
            if ascii::is_upper(ch) {
                if !first {
                    output.push('_');
                }
                output.push(ascii::lower(ch));
            } else {
                output.push(ch);
            }
            first = false;
        }

        output
    }

    pub fn classify<T: AsRef<str>>(input: T) -> String {
        Self::camelize_with_initial(input.as_ref(), true)
    }

    pub fn tableize<T: AsRef<str>>(input: T) -> String {
        Self::pluralize(Self::underscore(input))
    }

    pub fn humanize<T: AsRef<str>>(input: T) -> String {
        let mut output = String::with_capacity(input.as_ref().len());
        let mut first = true;

        for ch in input.as_ref().chars() {
            let mapped = if ch == '_' { ' ' } else { ch };
            if first {
                output.push(ascii::upper(mapped));
                first = false;
            } else {
                output.push(mapped);
            }
        }

        output
    }

    pub fn titleize<T: AsRef<str>>(input: T) -> String {
        let mut output = String::with_capacity(input.as_ref().len());
        let mut word_start = true;

        for ch in input.as_ref().chars() {
            let lower = ascii::lower(ch);
            if word_start {
                output.push(ascii::upper(lower));
            } else {
                output.push(lower);
            }
            word_start = ascii::is_space(ch);
        }

        output
    }

    pub fn dasherize<T: AsRef<str>>(input: T) -> String {
        input
            .as_ref()
            .chars()
            .map(|ch| if ch == '_' { '-' } else { ch })
            .collect()
    }

    pub fn parameterize<T: AsRef<str>>(input: T) -> String {
        let mut output = String::with_capacity(input.as_ref().len());

        for ch in input.as_ref().chars() {
            if ascii::is_alnum(ch) {
                output.push(ascii::lower(ch));
            } else if ch == ' ' {
                output.push('-');
            }
        }

        output
    }

    pub fn upcase<T: AsRef<str>>(input: T) -> String {
        input.as_ref().chars().map(ascii::upper).collect()
    }

    pub fn downcase<T: AsRef<str>>(input: T) -> String {
        input.as_ref().chars().map(ascii::lower).collect()
    }

    pub fn capitalize<T: AsRef<str>>(input: T) -> String {
        let mut chars = input.as_ref().chars();
        let mut output = String::with_capacity(input.as_ref().len());

        if let Some(first) = chars.next() {
            output.push(ascii::upper(first));
        }

        for ch in chars {
            output.push(ascii::lower(ch));
        }

        output
    }

    fn camelize_with_initial(input: &str, upper_first: bool) -> String {
        let mut output = String::with_capacity(input.len());
        let mut upper_next = upper_first;

        for ch in input.chars() {
            if ch == '_' {
                upper_next = true;
                continue;
            }

            if upper_next {
                output.push(ascii::upper(ch));
                upper_next = false;
            } else {
                output.push(ch);
            }
        }

        output
    }
}

